class LRUCache:
    def __init__(self, cap):
        self.cap = cap
        self.data = {}
        self.usage = []
    def get(self, k):
        if k not in self.data:
            return None
        self.usage.remove(k)
        self.usage.append(k)
        return self.data[k]
    def put(self, k, v):
        if k in self.data:
            self.usage.remove(k)
        elif len(self.data) >= self.cap:
            victim = self.usage.pop()
            del self.data[victim]
        self.data[k] = v
        self.usage.append(k)
